insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000002', 'en', null, 'Introduction to Psychology', 'A first tour of how the mind and behavior work — from the brain to memory, development, and disorders. Structure adapted from OpenStax Psychology 2e (CC BY 4.0).', null, 'foundations', 2, true, 'science', '{}')
